From a21e1cfaa2e18db6265809017290219c976083eb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:35:02 +0100
Subject: [PATCH] applets/taskmanager: add a separate action for
 Ctrl+middle-click

Middle-clicking a task could only do one thing, so people who wanted to
both open new windows and close tasks with the middle button had to pick
one. Add a "Ctrl+middle-clicking any task" setting with the same choices.

BUG: 427088
---
 applets/taskmanager/main.xml               | 12 ++++++++++++
 applets/taskmanager/qml/ConfigBehavior.qml |  9 +++++++++
 applets/taskmanager/qml/Task.qml           | 11 ++++++-----
 3 files changed, 27 insertions(+), 5 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..9302a3e7c2 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -118,6 +118,18 @@
       </choices>
       <default>2</default>
     </entry>
+    <entry name="ctrlMiddleClickAction" type="Enum">
+      <label>What to do on middle-mouse click on a task button while the Ctrl key is held.</label>
+      <choices>
+            <choice name="None"/>
+            <choice name="Close"/>
+            <choice name="NewInstance"/>
+            <choice name="ToggleMinimized"/>
+            <choice name="ToggleGrouping"/>
+            <choice name="BringToCurrentDesktop"/>
+      </choices>
+      <default>0</default>
+    </entry>
     <entry name="indicateAudioStreams" type="Bool">
       <label>Whether to indicate applications that are playing audio.</label>
       <default>true</default>
diff --git a/applets/taskmanager/qml/ConfigBehavior.qml b/applets/taskmanager/qml/ConfigBehavior.qml
index bd4b7cf008..1d2ce272eb 100644
--- a/applets/taskmanager/qml/ConfigBehavior.qml
+++ b/applets/taskmanager/qml/ConfigBehavior.qml
@@ -27,6 +27,7 @@ KCMUtils.SimpleKCM {
     property alias cfg_separateLaunchers: separateLaunchers.checked
     property alias cfg_hideLauncherOnStart: hideLauncherOnStart.checked
     property alias cfg_middleClickAction: middleClickAction.currentIndex
+    property alias cfg_ctrlMiddleClickAction: ctrlMiddleClickAction.currentIndex
     property alias cfg_wheelEnabled: wheelEnabled.currentIndex
     property alias cfg_wheelSkipMinimized: wheelSkipMinimized.checked
     property alias cfg_showOnlyCurrentScreen: showOnlyCurrentScreen.checked
@@ -198,6 +199,14 @@ KCMUtils.SimpleKCM {
             ]
         }

+        QQC2.ComboBox {
+            id: ctrlMiddleClickAction
+            Kirigami.FormData.label: i18nc("@label:listbox completes sentence like: … does nothing", "Ctrl+middle-clicking any task:")
+            Layout.fillWidth: true
+            Layout.minimumWidth: Kirigami.Units.gridUnit * 14
+            model: middleClickAction.model
+        }
+
         Item {
             Kirigami.FormData.isSection: true
         }
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..8733524438 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -435,15 +435,16 @@ PlasmaCore.ToolTipArea {
         acceptedButtons: Qt.MiddleButton | Qt.BackButton | Qt.ForwardButton
         onTapped: (eventPoint, button) => {
             if (button === Qt.MiddleButton) {
-                if (Plasmoid.configuration.middleClickAction === TaskManagerApplet.Backend.NewInstance) {
+                const action = (point.modifiers & Qt.ControlModifier) ? Plasmoid.configuration.ctrlMiddleClickAction : Plasmoid.configuration.middleClickAction;
+                if (action === TaskManagerApplet.Backend.NewInstance) {
                     tasksModel.requestNewInstance(modelIndex());
-                } else if (Plasmoid.configuration.middleClickAction === TaskManagerApplet.Backend.Close) {
+                } else if (action === TaskManagerApplet.Backend.Close) {
                     tasksModel.requestClose(modelIndex());
-                } else if (Plasmoid.configuration.middleClickAction === TaskManagerApplet.Backend.ToggleMinimized) {
+                } else if (action === TaskManagerApplet.Backend.ToggleMinimized) {
                     tasksModel.requestToggleMinimized(modelIndex());
-                } else if (Plasmoid.configuration.middleClickAction === TaskManagerApplet.Backend.ToggleGrouping) {
+                } else if (action === TaskManagerApplet.Backend.ToggleGrouping) {
                     tasksModel.requestToggleGrouping(modelIndex());
-                } else if (Plasmoid.configuration.middleClickAction === TaskManagerApplet.Backend.BringToCurrentDesktop) {
+                } else if (action === TaskManagerApplet.Backend.BringToCurrentDesktop) {
                     TaskManagerApplet.TaskTools.foreachChildTask((childIndex) => {
                         tasksModel.requestVirtualDesktops(childIndex, [virtualDesktopInfo.currentDesktopByScreenGeometry(tasksModel.data(childIndex, TaskManager.AbstractTasksModel.ScreenGeometry))]);
                     }, modelIndex(), tasksModel);
-- 
